export type WorkingContextTaskStatus =
  | "pending"
  | "accepted"
  | "rejected"
  | "completed"
  | "failed"
  | "cancelled";

export interface WorkingContextTask {
  taskId: string;
  status: WorkingContextTaskStatus;
  prompt?: string;
  result?: unknown;
  error?: unknown;
  createdAt: string;
  updatedAt: string;
}

export interface WorkingContextEvent {
  eventId: string;
  batchIdempotencyKey: string;
  workspaceId: string;
  taskId: string;
  type: "submitted" | "accepted" | "rejected" | "completed" | "failed" | "cancelled";
  timestamp: string;
  payload?: Record<string, unknown>;
}

export interface WorkingContextProjection {
  workspaceId: string;
  tasks: WorkingContextTask[];
  pending: WorkingContextTask[];
  accepted: WorkingContextTask[];
  rejected: WorkingContextTask[];
  completed: WorkingContextTask[];
  failed: WorkingContextTask[];
  cancelled: WorkingContextTask[];
}

export interface SubmitWorkingContextInput {
  workspaceId: string;
  taskId: string;
  batchIdempotencyKey: string;
  prompt?: string;
  timestamp?: string;
  payload?: Record<string, unknown>;
}

export interface WorkingContextLedgerOptions {
  workspaceId: string;
}

export function isWorkingContextEvent(value: unknown): value is WorkingContextEvent {
  if (!value || typeof value !== "object") return false;
  const event = value as Partial<WorkingContextEvent>;
  return (
    typeof event.eventId === "string" &&
    typeof event.batchIdempotencyKey === "string" &&
    typeof event.workspaceId === "string" &&
    typeof event.taskId === "string" &&
    typeof event.type === "string" &&
    typeof event.timestamp === "string" &&
    (event.type === "submitted" ||
      event.type === "accepted" ||
      event.type === "rejected" ||
      event.type === "completed" ||
      event.type === "failed" ||
      event.type === "cancelled")
  );
}

export function parseWorkingContextLedger(contents: string): WorkingContextEvent[] {
  const events: WorkingContextEvent[] = [];
  for (const line of contents.split(/\r?\n/u)) {
    if (!line.trim()) continue;
    const parsed: unknown = JSON.parse(line);
    if (isWorkingContextEvent(parsed)) events.push(parsed);
  }
  return events;
}

export function serializeWorkingContextEvent(event: WorkingContextEvent): string {
  return `${JSON.stringify(event)}\n`;
}

export function projectWorkingContextEvents(
  events: readonly WorkingContextEvent[],
  options: WorkingContextLedgerOptions,
): WorkingContextProjection {
  const tasks = new Map<string, WorkingContextTask>();

  for (const event of events) {
    if (event.workspaceId !== options.workspaceId) continue;

    const previous = tasks.get(event.taskId);
    const status: WorkingContextTaskStatus =
      event.type === "submitted" ? "pending" : event.type;
    const next: WorkingContextTask = {
      taskId: event.taskId,
      status,
      createdAt: previous?.createdAt ?? event.timestamp,
      updatedAt: event.timestamp,
    };

    if (previous) {
      if (previous.prompt !== undefined) next.prompt = previous.prompt;
      if (previous.result !== undefined) next.result = previous.result;
      if (previous.error !== undefined) next.error = previous.error;
    }
    if (event.payload) {
      if (typeof event.payload.prompt === "string") next.prompt = event.payload.prompt;
      if (Object.prototype.hasOwnProperty.call(event.payload, "result")) {
        next.result = event.payload.result;
      }
      if (Object.prototype.hasOwnProperty.call(event.payload, "error")) {
        next.error = event.payload.error;
      }
    }

    tasks.set(event.taskId, next);
  }

  const ordered = [...tasks.values()].sort((left, right) => {
    const byCreation = left.createdAt.localeCompare(right.createdAt);
    return byCreation || left.taskId.localeCompare(right.taskId);
  });
  const byStatus = (status: WorkingContextTaskStatus): WorkingContextTask[] =>
    ordered.filter((task) => task.status === status);

  return {
    workspaceId: options.workspaceId,
    tasks: ordered,
    pending: byStatus("pending"),
    accepted: byStatus("accepted"),
    rejected: byStatus("rejected"),
    completed: byStatus("completed"),
    failed: byStatus("failed"),
    cancelled: byStatus("cancelled"),
  };
}

export function hasWorkingContextBatch(
  events: readonly WorkingContextEvent[],
  workspaceId: string,
  batchIdempotencyKey: string,
): boolean {
  return events.some(
    (event) =>
      event.workspaceId === workspaceId &&
      event.batchIdempotencyKey === batchIdempotencyKey,
  );
}

import { promises as fs } from "node:fs";
import path from "node:path";
import {
  hasWorkingContextBatch,
  parseWorkingContextLedger,
  projectWorkingContextEvents,
  serializeWorkingContextEvent,
  type SubmitWorkingContextInput,
  type WorkingContextEvent,
  type WorkingContextProjection,
} from "../../shared/task-ledger-working-context";

const LEDGER_DIRECTORY = ".task-ledger";
const WORKING_CONTEXT_LEDGER = "working-context.jsonl";

exfunction encodeWorkspaceId(workspaceId: string): string {
  return encodeURIComponent(workspaceId);
}

export class TaskLedgerWorkingContext {
  private readonly workspaceRoot: string;
  private readonly workspaceId: string;

  public constructor(workspaceRoot: string, workspaceId: string) {
    this.workspaceRoot = workspaceRoot;
    this.workspaceId = workspaceId;
  }

  public get ledgerPath(): string {
    return path.join(
      this.workspaceRoot,
      LEDGER_DIRECTORY,
      `${encodeWorkspaceId(this.workspaceId)}-${WORKING_CONTEXT_LEDGER}`,
    );
  }

  private async readEvents(): Promise<WorkingContextEvent[]> {
    let contents: string;
    try {
      contents = await fs.readFile(this.ledgerPath, "utf8");
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
      throw error;
    }
    return parseWorkingContextLedger(contents);
  }

  public async append(event: WorkingContextEvent): Promise<boolean> {
    if (event.workspaceId !== this.workspaceId) {
      throw new Error(
        `Working Context event workspace ${event.workspaceId} does not match ${this.workspaceId}`,
      );
    }

    const existing = await this.readEvents();
    if (
      hasWorkingContextBatch(
        existing,
        this.workspaceId,
        event.batchIdempotencyKey,
      )
    ) {
      return false;
    }

    await fs.mkdir(path.dirname(this.ledgerPath), { recursive: true });
    await fs.appendFile(this.ledgerPath, serializeWorkingContextEvent(event), {
      encoding: "utf8",
      flag: "a",
    });
    return true;
  }

  public async submit(
    input: SubmitWorkingContextInput,
  ): Promise<{ appended: boolean; event: WorkingContextEvent }> {
    if (input.workspaceId !== this.workspaceId) {
      throw new Error(
        `Working Context input workspace ${input.workspaceId} does not match ${this.workspaceId}`,
      );
    }

    const event: WorkingContextEvent = {
      eventId: `${input.batchIdempotencyKey}:${input.taskId}`,
      batchIdempotencyKey: input.batchIdempotencyKey,
      workspaceId: input.workspaceId,
      taskId: input.taskId,
      type: "submitted",
      timestamp: input.timestamp ?? new Date().toISOString(),
      ...(input.payload === undefined ? {} : { payload: input.payload }),
    };
    const appended = await this.append(event);
    return { appended, event };
  }

  public async projection(): Promise<WorkingContextProjection> {
    const events = await this.readEvents();
    return projectWorkingContextEvents(events, { workspaceId: this.workspaceId });
  }

  public async read(): Promise<WorkingContextProjection> {
    return this.projection();
  }
}

export async function appendWorkingContextEvent(
  workspaceRoot: string,
  workspaceId: string,
  event: WorkingContextEvent,
): Promise<boolean> {
  return new TaskLedgerWorkingContext(workspaceRoot, workspaceId).append(event);
}

export async function submitWorkingContext(
  workspaceRoot: string,
  input: SubmitWorkingContextInput,
): Promise<{ appended: boolean; event: WorkingContextEvent }> {
  return new TaskLedgerWorkingContext(workspaceRoot, input.workspaceId).submit(input);
}

export async function readWorkingContext(
  workspaceRoot: string,
  workspaceId: string,
): Promise<WorkingContextProjection> {
  return new TaskLedgerWorkingContext(workspaceRoot, workspaceId).read();
}

export async function projectWorkingContext(
  workspaceRoot: string,
  workspaceId: string,
): Promise<WorkingContextProjection> {
  return readWorkingContext(workspaceRoot, workspaceId);
}

